"""Generate crawlable static pages. Run python3 build.py after editing content/site.json."""
from pathlib import Path
from html import escape as e
from xml.sax.saxutils import escape as xe
from urllib.parse import urlsplit
import json, os, re, shutil

ROOT = Path(__file__).parent
D = json.loads((ROOT / 'content/site.json').read_text())
OUT = Path(os.environ.get('OUTPUT_DIR', str(ROOT / 'dist'))).resolve()
OUT.mkdir(exist_ok=True)
for name in ('assets', 'works', 'read', 'about'):
    if (OUT / name).exists(): shutil.rmtree(OUT / name)
(OUT / 'assets').mkdir()
for name in ('style.css', 'app.js', 'favicon.svg'):
    shutil.copy(ROOT / name, OUT / 'assets' / name)
ORIGIN = (os.environ.get('SITE_URL') or D.get('origin') or 'http://localhost:8000').rstrip('/')
parsed_origin = urlsplit(ORIGIN)
if parsed_origin.scheme not in ('http', 'https') or not parsed_origin.netloc or parsed_origin.query or parsed_origin.fragment:
    raise ValueError('SITE_URL must be an absolute HTTP(S) site URL without query or fragment')
BASE = parsed_origin.path.rstrip('/')
pages = []
def words(ch): return sum(len(p) for p in ch['paragraphs'])
def url(path): return ORIGIN + path
def write(path, body):
    if BASE:
        body = re.sub(r'(href|src|data-path)="(/(?!/)[^"]*)"', lambda m: m[1]+'="'+BASE+m[2]+'"', body)
    p = OUT / path.lstrip('/')
    if path.endswith('/'): p = p / 'index.html'
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(body)
    if path != '/404.html': pages.append(path)
def header(active='', quiet=False):
    return f'''<a class="skip" href="#main">跳到正文</a><header class="header {'quiet' if quiet else ''}"><a class="brand" href="/" aria-label="{e(D['name'])}首页"><span class="brand-mark" aria-hidden="true">d.</span><span>{e(D['name'])}</span></a><nav aria-label="主导航"><a {'aria-current="page"' if active=='works' else ''} href="/works/">作品目录</a><a {'aria-current="page"' if active=='about' else ''} href="/about/">关于</a><a class="nav-index" href="/works/#chapters" aria-label="浏览所有章节">目录 <span aria-hidden="true">↗</span></a></nav></header>'''
def footer():
    return f'''<footer class="footer"><a class="footer-brand" href="/">{e(D['name'])}</a><span>故事在这里，慢慢展开。</span><div><a href="/feed.xml">订阅更新 RSS ↗</a><a href="/about/">关于本站</a></div><small>© 2026 {e(D['name'])} · 作品演示版 · 正式作品与署名待补充</small></footer>'''
def page(title, description, path, body, active='', reader=False, structured=None, notfound=False):
    ld = structured or {'@context':'https://schema.org','@type':'WebSite','name':D['name'],'url':url('/')}
    return f'''<!doctype html><html lang="zh-CN" data-theme="light" data-base="{e(BASE,quote=True)}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · {e(D['name'])}</title><meta name="description" content="{e(description,quote=True)}"><meta name="color-scheme" content="dark light"><meta name="theme-color" content="#ffffff"><meta name="robots" content="{'noindex' if notfound else 'index,follow'}"><link rel="canonical" href="{e(url(path))}"><meta property="og:type" content="{'article' if reader else 'website'}"><meta property="og:title" content="{e(title,quote=True)} · {e(D['name'])}"><meta property="og:description" content="{e(description,quote=True)}"><meta property="og:url" content="{e(url(path))}"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="alternate" type="application/rss+xml" title="daswohltemperierte 连载更新" href="/feed.xml"><link rel="stylesheet" href="/assets/style.css"><script type="application/ld+json">{json.dumps(ld,ensure_ascii=False).replace('<','\\u003c')}</script><script src="/assets/app.js" defer></script></head><body class="{'reading' if reader else ''}">{header(active, reader)}{body}{footer()}<div id="toast" role="status" aria-live="polite"></div></body></html>'''
W = D['works'][0]
def wp(w): return '/works/' + w['slug'] + '/'
def cp(w,c): return '/read/' + w['slug'] + '/' + c['slug'] + '/'
def cover(w, compact=False):
    return f'''<div class="book-cover {'compact' if compact else ''}" role="img" aria-label="长夜来信演示封面，抽象夜色与一道光"><div class="cover-top">DASWOHLTEMPERIERTE / 001<span>DEMO EDITION</span></div><div class="cover-light" aria-hidden="true"></div><div class="cover-rule" aria-hidden="true"></div><div class="cover-title"><small>{e(w['english_title'])}</small><strong>长夜<br>来信<span class="cover-dot">.</span></strong><span class="cover-author">演示作品 / 作者待署名</span></div><div class="cover-bottom"><span>FICTION — IN SERIAL</span><span>第一卷</span></div></div>'''
def rows(w, limit=None):
    chapters = w['chapters'][:limit] if limit else w['chapters']
    return ''.join(f'''<a class="chapter-row" data-search="{e(c['title'])} {i:02d}" href="{cp(w,c)}"><span class="chapter-num">{i:02d}</span><span class="chapter-name">{e(c['title'])}{'<em>最新</em>' if i==len(w['chapters']) else ''}</span><span class="chapter-meta">{words(c):,} 字 <span> / {c['date'][5:].replace('-','.')} 演示</span></span><span class="row-arrow" aria-hidden="true">↗</span></a>''' for i,c in enumerate(chapters,1))
def resume(w): return f'<a class="button secondary resume" href="{cp(w,w["chapters"][0])}" data-resume="{w["slug"]}" hidden>继续阅读 <span aria-hidden="true">↗</span></a>'
home = f'''<main id="main"><section class="hero"><div class="hero-intro"><div class="eyebrow"><span class="live-dot"></span> 一个安静的小说阅读空间</div><h1>故事未完，<br>夜还<span class="italic-word">很长。</span></h1><p class="hero-desc">长篇、连载，以及故事之间的留白。<br>找一个舒服的位置，从这一页开始。</p><a class="text-link" href="{wp(W)}">进入连载 <span aria-hidden="true">↗</span></a></div><div class="hero-aside"><span class="vertical-note">READ AT YOUR OWN PACE</span><a class="cover-link" href="{wp(W)}">{cover(W)}</a><div class="cover-caption"><span>01 / 当前作品</span><span>演示连载 <span class="live-dot"></span></span></div></div><div class="hero-bottom"><span>FICTION / WORDS / AFTER HOURS</span><a href="#current">向下阅读 ↓</a><span>SCROLL TO EXPLORE</span></div></section><section id="current" class="section current"><div class="section-heading"><div><span class="eyebrow">01 / THE SERIAL</span><h2>正在书写</h2></div><span class="muted">一个故事，一次相逢。</span></div><div class="work-summary"><div><div class="tags"><span class="accent">{e(W['status'])}</span><span>都市</span><span>悬疑</span></div><h3><a href="{wp(W)}">{e(W['title'])}</a></h3><p>{e(W['subtitle'])}</p><p class="muted work-description">{e(W['description'])}</p><div class="button-row"><a class="button" href="{cp(W,W['chapters'][0])}">从第一章开始 <span aria-hidden="true">↗</span></a>{resume(W)}</div></div><div class="work-data"><div><strong>01—{len(W['chapters']):02d}</strong><span>演示章节 / 按顺序阅读</span></div><div><strong>{sum(words(c) for c in W['chapters']):,}<small>字</small></strong><span>演示正文 / 正式内容待发布</span></div><a class="text-link" href="{wp(W)}">作品详情与目录 ↗</a></div></div></section><section class="section latest"><div class="section-heading"><div><span class="eyebrow">02 / THE CHAPTERS</span><h2>章节一览</h2></div><a class="text-link" href="{wp(W)}#chapters">查看全部 ↗</a></div><div class="chapter-table">{rows(W)}</div><div class="demo-notice"><span aria-hidden="true">↳</span> 首版展示：封面与小说为演示内容，等待换上你的故事。</div></section><section class="closing"><span class="eyebrow">BETWEEN THE LINES</span><p>把时间留给故事，<br>把下一页留给你。</p><a class="text-link" href="/about/">关于这个空间 ↗</a></section></main>'''
write('/',page('首页',D['description'],'/',home))
workbody=f'''<main id="main"><div class="breadcrumb"><a href="/">首页</a><span>/</span><a href="/works/">作品</a><span>/</span><span>{e(W['title'])}</span></div><section class="work-hero"><div class="work-cover">{cover(W,True)}</div><div class="work-info"><span class="eyebrow">THE SERIAL / 001</span><div class="tags"><span class="accent">演示连载</span><span>都市</span><span>悬疑</span></div><h1>{e(W['title'])}</h1><p class="subtitle">{e(W['subtitle'])}</p><p class="work-description">{e(W['description'])}</p><div class="work-facts"><span>{len(W['chapters'])} 章</span><span>{sum(words(c) for c in W['chapters']):,} 字演示正文</span><span>作者待署名</span></div><div class="button-row"><a class="button" href="{cp(W,W['chapters'][0])}">开始阅读 ↗</a>{resume(W)}</div></div></section><section id="chapters" class="section contents"><div class="section-heading"><div><span class="eyebrow">TABLE OF CONTENTS</span><h2>章节目录 <small>/ {len(W['chapters']):02d}</small></h2></div><div class="catalog-tools"><label class="search"><span aria-hidden="true">⌕</span><input id="chapter-search" type="search" placeholder="搜索章节" aria-label="搜索章节标题"></label><button class="sort-button" id="sort" aria-label="切换章节排列顺序" aria-pressed="false">正序 ↓</button></div></div><p class="volume-label">第一卷 <span>· 演示内容</span></p><div class="chapter-table" id="chapter-list">{rows(W)}</div><p id="no-results" class="empty-state" hidden>没有找到这章。试试其他标题或章节号。</p><p id="search-status" class="sr-only" role="status" aria-live="polite"></p><p class="demo-notice">演示内容不代表正式连载；你的章节可以按此目录持续追加。</p></section></main>'''
write(wp(W),page(W['title']+' · 作品与目录',W['description'],wp(W),workbody,'works'))
archive = f'''<main id="main" class="archive-page"><div class="breadcrumb"><a href="/">首页</a><span>/</span><span>作品目录</span></div><div class="page-title"><span class="eyebrow">THE COLLECTION / 01</span><h1>作品目录<span class="accent">.</span></h1><p class="muted">故事各有去处，在这里找到起点。</p></div><a class="archive-work" href="{wp(W)}"><div>{cover(W,True)}</div><div><div class="tags"><span class="accent">演示连载</span><span>都市 / 悬疑</span></div><h2>{e(W['title'])}</h2><p>{e(W['subtitle'])}</p><p class="muted">{e(W['description'])}</p><span class="text-link">{len(W['chapters'])} 个章节 · 进入作品 ↗</span></div></a><section id="chapters" class="section"><div class="section-heading"><h2>全部章节</h2><span class="muted">长夜来信 / 演示</span></div>{rows(W)}</section></main>'''
write('/works/',page('作品目录','浏览长篇连载、作品介绍与章节目录。','/works/',archive,'works'))
for idx,c in enumerate(W['chapters']):
    path=cp(W,c)
    prev = f'<a href="{cp(W,W["chapters"][idx-1])}">← 上一章</a>' if idx else '<span class="muted">已是第一章</span>'
    nex = f'<a href="{cp(W,W["chapters"][idx+1])}">下一章 →</a>' if idx+1<len(W['chapters']) else '<span class="muted">已读至演示末章</span>'
    options=''.join(f'<a {"aria-current=\"page\"" if x==c else ""} href="{cp(W,x)}"><span>{i:02d}</span>{e(x["title"])}</a>' for i,x in enumerate(W['chapters'],1))
    body=f'''<div class="reading-progress" aria-hidden="true"><span id="progress-bar"></span></div><main id="main" data-work="{W['slug']}" data-chapter="{c['slug']}" data-title="{e(c['title'])}" data-path="{path}"><div class="reader-top"><a href="{wp(W)}">← {e(W['title'])} / 目录</a><span>CHAPTER {idx+1:02d} / {len(W['chapters']):02d}</span></div><div class="reader-layout"><aside class="reader-sidebar"><span class="eyebrow">本卷目录</span><h2>{e(W['title'])}</h2><nav aria-label="章节目录">{options}</nav><p>慢慢读。<br>故事会在这里等你。</p></aside><div class="reader-column"><header class="chapter-heading"><span class="eyebrow">CHAPTER {idx+1:02d}</span><h1>{e(c['title'])}</h1><p>{c['date'].replace('-','.')} <span> / </span>{words(c)} 字 <span> / </span>演示章节</p></header><div class="reader-toolbar" aria-label="阅读设置"><div><button id="smaller" aria-label="缩小正文" title="缩小正文">A−</button><span id="font-size" aria-live="polite">20</span><button id="larger" aria-label="放大正文" title="放大正文">A＋</button><span class="toolbar-line"></span><button id="font-toggle" aria-label="切换正文字体" aria-pressed="false">宋体</button></div><div><button class="theme-dot night" data-theme-choice="dark" aria-label="夜间阅读" aria-pressed="false"></button><button class="theme-dot paper" data-theme-choice="paper" aria-label="暖纸阅读" aria-pressed="false"></button><button class="theme-dot light" data-theme-choice="light" aria-label="白底阅读" aria-pressed="true"></button><button id="bookmark" aria-label="收藏本章到此浏览器" aria-pressed="false" title="收藏本章">☆</button></div></div><article id="chapter-text" class="prose" aria-label="章节正文">{('<p class="sample-note">'+e(c['notice'])+'</p>') if c.get('notice') else ''}{''.join(f'<p>{e(p)}</p>' for p in c['paragraphs'])}</article><div class="chapter-end"><span>— 本章完 —</span><button class="text-link" id="copy-link">复制本章链接 ↗</button></div><nav class="chapter-navigation" aria-label="翻页">{prev}<a href="{wp(W)}#chapters">章节目录</a>{nex}</nav><div class="reader-note">阅读位置与收藏仅保存在当前浏览器。<a href="/about/#reading-data">了解详情 ↗</a></div></div></div><button class="back-top" id="back-top" aria-label="返回顶部">↑</button></main>'''
    ld={'@context':'https://schema.org','@type':'Chapter','name':c['title']+'（演示）','url':url(path),'inLanguage':'zh-CN','position':idx+1,'isPartOf':{'@type':'Book','name':W['title']+'（演示作品）','url':url(wp(W))}}
    write(path,page(c['title']+' · '+W['title'],c['paragraphs'][0],path,body,reader=True,structured=ld))
about='''<main id="main" class="about-page"><div class="breadcrumb"><a href="/">首页</a><span>/</span><span>关于</span></div><div class="page-title"><span class="eyebrow">A NOTE FROM THE MARGIN</span><h1>在文字之间<span class="accent">.</span></h1><p class="about-lead">一个让故事安静生长的地方。</p></div><div class="about-body"><section><span class="eyebrow">01 / THIS SPACE</span><h2>关于 daswohltemperierte</h2><p>这里为长篇小说与持续更新的故事而设。作品有自己的目录，每一章都有可以独立访问和分享的网址。</p><p>daswohltemperierte 是一个个人小说阅读空间。作者笔名、个人简介和正式作品将在确认后补充。目前的《长夜来信》及其封面均为网站演示内容，并非作者正式作品。</p></section><section><span class="eyebrow">02 / READING</span><h2>按你的节奏阅读</h2><p>阅读页可以调整字号、切换宋体与黑体，以及选择白底、暖纸、夜间三种主题。作品目录支持搜索章节与切换正序、倒序。</p><p>阅读过的作品会出现“继续阅读”入口。你也可以收藏章节，或者通过 RSS 订阅更新。</p></section><section id="reading-data"><span class="eyebrow">03 / YOUR READING DATA</span><h2>关于阅读记录</h2><p>阅读进度、收藏和排版偏好保存在当前浏览器的本地存储中，不会上传服务器，也不能跨设备同步。隐私浏览模式或清理浏览器数据可能会删除这些记录。</p><p>本站未添加广告、访问统计脚本或读者账号系统。</p><button class="button secondary" id="clear-data">清除此浏览器的阅读记录</button><p id="clear-status" role="status"></p></section></div></main>'''
write('/about/',page('关于','关于 daswohltemperierte、阅读设置以及本地阅读记录。','/about/',about,'about'))
write('/404.html',page('这一页暂时没有故事','页面不存在，请回到作品目录。','/404.html','<main id="main" class="not-found"><span class="eyebrow">404 / PAGE NOT FOUND</span><h1>这一页，<br>还没有故事。</h1><p>地址可能有误，也可能是章节尚未发布。</p><a class="button" href="/works/">回到作品目录 ↗</a></main>',notfound=True))
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+url('/sitemap.xml')+'\n')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+xe(url(p))+'</loc></url>' for p in pages)+'</urlset>')
items=''.join(f'<item><title>{xe(W["title"]+" · "+c["title"]+"（演示）")}</title><link>{xe(url(cp(W,c)))}</link><guid isPermaLink="true">{xe(url(cp(W,c)))}</guid><description>{xe(c["paragraphs"][1])}</description></item>' for c in reversed(W['chapters']))
(OUT/'feed.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>daswohltemperierte · 连载更新</title><link>'+xe(url('/'))+'</link><description>'+xe(D['description'])+'</description><language>zh-CN</language>'+items+'</channel></rss>')
(OUT/'.nojekyll').touch()
print(f'Generated {len(pages)} pages + 404, sitemap, RSS, robots.txt at {ORIGIN}')
